def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Recolor every complete separator row or column of color 1 to color 2.
    for r, row in enumerate(grid):
        if all(value == 1 for value in row):
            out[r] = [2] * w
    for c in range(w):
        if all(grid[r][c] == 1 for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    return out

